// Reproduce code using bpmn-js v3.0.3
import BpmnModeler from 'bpmn-js/lib/Modeler';

// 1) Provide your example BPMN XML (from the bug repro)
const exampleXml = `<?xml version="1.0" encoding="UTF-8"?>
<bpmn:definitions xmlns:bpmn="http://www.omg.org/spec/BPMN/20100524/MODEL"
                  xmlns:bpmndi="http://www.omg.org/spec/BPMN/20100524/DI"
                  xmlns:dc="http://www.omg.org/spec/DD/20100524/DC"
                  id="Definitions_1"
                  targetNamespace="http://bpmn.io/schema/bpmn">

  <bpmn:process id="Process_1" isExecutable="false">
    <bpmn:startEvent id="StartEvent_1" name="A" />
    <bpmn:task id="Task_1" />
    <bpmn:endEvent id="EndEvent_1" name="B" />
    <bpmn:sequenceFlow id="Flow_1" sourceRef="StartEvent_1" targetRef="Task_1" />
    <bpmn:sequenceFlow id="Flow_2" sourceRef="Task_1" targetRef="EndEvent_1" />
  </bpmn:process>

  <bpmn:participant id="Participant_1" processRef="Process_1" />

  <bpmndi:BPMNDiagram id="BPMNDiagram_1">
    <bpmndi:BPMNPlane id="BPMNPlane_1" bpmnElement="Participant_1">
      <!-- lanes omitted for brevity -->
      <!-- shapes and edges for StartEvent, Task, EndEvent and Flows -->
    </bpmndi:BPMNPlane>
  </bpmndi:BPMNDiagram>
</bpmn:definitions>`;

// 2) Initialize the modeler
const modeler = new BpmnModeler({ container: '#canvas' });

async function reproduceCopyPasteMissingLabels() {
  // import the BPMN with pool and labeled events
  await modeler.importXML(exampleXml);

  const elementRegistry = modeler.get('elementRegistry');
  const canvas = modeler.get('canvas');
  const copyPaste = modeler.get('copyPaste');
  const modeling = modeler.get('modeling');

  canvas.zoom('fit-viewport');

  // 3) Gather the children of the pool (Participant_1)
  const participant = elementRegistry.get('Participant_1');
  const children = elementRegistry.filter(el => el.parent === participant && el.type !== 'label');

  // 4) Copy those shapes (labels are handled specially under the hood)
  copyPaste.copy(children);

  // 5) Remove the originals from the diagram
  children.forEach(shape => modeling.removeShape(shape));

  // 6) Paste them back into the root process (Process_1)
  const rootShape = elementRegistry.get('Process_1');
  // paste at offset so we can see them clearly
  const pasteLocation = { x: 300, y: 150 };
  const pasted = copyPaste.paste(pasteLocation, rootShape);

  console.log('Pasted elements:', pasted);
  // Inspect in the rendered canvas: the circles and rectangle are there,
  // but you will notice that event labels „A“ and „B“ are missing.
}

reproduceCopyPasteMissingLabels();
